template:
use std::fmt::Display;

fn duplicate<T>(val: &T) -> (T, T)
where
    T: ⟦b1⟧,
{
    (val.clone(), val.clone())
}

fn show<T: ⟦b2⟧>(val: T) {
    println!("{val} and {val}");
}

fn main() {
    let s = String::from("rust");
    let (a, b) = duplicate(&s);
    show(a);
    show(b);
}

tests:
#[test]
fn duplicates_and_shows() {
    let s = String::from("test");
    let (a, b) = duplicate(&s);
    assert_eq!(a, "test");
    assert_eq!(b, "test");
}
